// Regenerate src/hypothesis/example-confbias.data.ts from example-confbias.json.
// The JSON is the canonical file (a byte copy of the Hypothesizer app's example); the .ts module
// exists so the library needs no JSON-module import support. tests/example.test.ts checks they agree.
import fs from "node:fs";

const json = fs.readFileSync(new URL("../src/hypothesis/example-confbias.json", import.meta.url), "utf8");
const data = JSON.parse(json);
const out =
  "// GENERATED by scripts/build-example-data.mjs from example-confbias.json. Do not edit.\n" +
  `export const CONFBIAS_EXAMPLE_DATA: unknown = ${JSON.stringify(data, null, 2)};\n`;
fs.writeFileSync(new URL("../src/hypothesis/example-confbias.data.ts", import.meta.url), out);
console.log("wrote src/hypothesis/example-confbias.data.ts");
